beforeSaveCustomScript:
$pctChanged = entity\isAttributeChanged('commissionPercent');
$feeChanged = entity\isAttributeChanged('commissionAmount');
$grossChanged = entity\isAttributeChanged('amountGross');

if (amountGross == '') {
    amountGross = null;
}
if (commissionPercent == '') {
    commissionPercent = null;
}
if (commissionAmount == '') {
    commissionAmount = null;
}

if (commissionPercent == null) {
    commissionPercent = 0;
}
if (commissionAmount == null) {
    commissionAmount = 0;
}

if (amountGross == null) {
    amountGross = 0;
    commissionAmount = 0;
    commissionPercent = 0;
} else {
    if ($feeChanged && !$pctChanged) {
        if (amountGross != 0) {
            commissionPercent = number\round(commissionAmount * 100.0 / amountGross, 4);
        } else {
            commissionPercent = 0;
        }
    } else if ($pctChanged && !$feeChanged) {
        commissionAmount = number\round(amountGross * commissionPercent / 100.0, 2);
    } else if ($feeChanged && $pctChanged) {
        if (commissionAmount == 0 && commissionPercent != 0 && amountGross != 0) {
            commissionAmount = number\round(amountGross * commissionPercent / 100.0, 2);
        } else if (amountGross != 0) {
            commissionPercent = number\round(commissionAmount * 100.0 / amountGross, 4);
        } else {
            commissionPercent = 0;
        }
    } else if ($grossChanged) {
        if (amountGross == 0) {
            commissionAmount = 0;
            commissionPercent = 0;
        } else {
            commissionAmount = number\round(amountGross * commissionPercent / 100.0, 2);
        }
    } else if (entity\isNew()) {
        if (commissionPercent != 0 && commissionAmount == 0) {
            commissionAmount = number\round(amountGross * commissionPercent / 100.0, 2);
        } else if (commissionAmount != 0 && commissionPercent == 0 && amountGross != 0) {
            commissionPercent = number\round(commissionAmount * 100.0 / amountGross, 4);
        }
    }

    if (amountGross != 0 || commissionAmount != 0) {
        if (amountGrossCurrency != null) {
            commissionAmountCurrency = amountGrossCurrency;
            amountCurrency = amountGrossCurrency;
        }
        amount = number\round(amountGross - commissionAmount, 2);
        if (amount < 0) {
            amount = 0;
        }
    } else if ($grossChanged) {
        commissionAmount = 0;
        commissionPercent = 0;
    }
}

if (transactionDate == null) {
    transactionDate = datetime\today();
}
if (amount == null) {
    amount = 0;
}
if (entryType == 'Income') {
    amountIn = amount;
    amountOut = 0;
} else if (entryType == 'Expense') {
    amountOut = amount;
    amountIn = 0;
}
if (internalClassification == 'Donation' && donationPaymentReference != null && donationPaymentReference != '') {
    name = string\concatenate(transactionDate, ' | ', donationPaymentReference);
    if (donationDonorCategory != null && donationDonorCategory != '') {
        name = string\concatenate(name, ' | ', donationDonorCategory);
    }
    description = string\concatenate('Donazione ', donationPaymentProvider, ' ordine ', donationPaymentReference);
    if (donationComment != null && donationComment != '') {
        description = string\concatenate(description, '\nComment: ', donationComment);
    }
} else {
    name = string\concatenate(transactionDate, ' — ', description);
}
